-- ============================================================================
-- B5 FOLLOW-ON W5 (part c), section 3: 20261028c_w5_welldata.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 3
-- (D4 picks A and B) and the spec docs/graded-field-audit/w5c/welldata.json.
-- Owner approved D1 to D7 as recommended, 2026-09-21.
--
-- INTERMEDIATE (pick A: re-case)
--   Section 3 pick A: every graded value was printed by the intermediate
--   walkthrough and the import panel opened on feet_20. The capstone moves to
--   the ODUMA case, which no panel preloads.
--   RE-KEY start_md_m (expected 1493.52001953125, tol 0.01)
--       -> oduma3_start_md_m 'oduma3_feet: start depth (converted)' m, expected 2139.696044921875, tol 0.01
--   RE-KEY stop_md_m (expected 1584.9599609375, tol 0.01)
--       -> oduma3_stop_md_m 'oduma3_feet: stop depth (converted)' m, expected 2169.26171875, tol 0.01
--   RE-KEY step_m (expected 0.609619140625, tol 0.001)
--       -> oduma3_import_step_m 'oduma3_feet: depth step (converted)' m, expected 0.076171875, tol 0.001
--   RE-KEY converted_curves (expected 2, tol 0)
--       -> oduma3_converted_curves 'oduma3_feet: curves unit-converted' count, expected 3, tol 0
--   RE-KEY recognized_kinds (expected 4, tol 0)
--       -> oduma3_recognized_kinds 'oduma3_feet: curve kinds recognised' count, expected 6, tol 0
--   RE-KEY irregular_samples (expected 121, tol 0)
--       -> oduma4_n_samples 'oduma4_irregular: depth samples' count, expected 173, tol 0
--   PROMPT and DATASET replaced (the new case, stated in full; the W1 open-book label goes).
--
-- ADVANCED (pick A: re-case)
--   Section 3 pick A: every graded value was printed by the advanced walkthrough
--   and the campaign panel opened on the teaching campaign. The capstone moves
--   to the ODUMA campaign, which no panel preloads.
--   RE-KEY campaign_curves (expected 24, tol 0)
--       -> oduma_campaign_curves 'Curves imported across the ODUMA campaign' count, expected 31, tol 0
--   RE-KEY converted_files (expected 1, tol 0)
--       -> oduma_converted_files 'Files needing depth unit conversion' count, expected 3, tol 0
--   RE-KEY dead_curves (expected 1, tol 0)
--       -> oduma_dead_curves 'Dead curves detected' count, expected 2, tol 0
--   RE-KEY uniform_files (expected 5, tol 0)
--       -> oduma_uniform_files 'Files with a uniform depth step' count, expected 4, tol 0
--   RE-KEY wrapped_samples (expected 161, tol 0)
--       -> oduma1_wrapped_samples 'Depth samples in oduma1_wrapped' count, expected 207, tol 0
--   RE-KEY nullheavy_nulls (expected 272, tol 0)
--       -> oduma5_flagged_nulls 'Flagged nulls in oduma5_nulls' count, expected 525, tol 0
--   PROMPT and DATASET replaced (the new case, stated in full; the W1 open-book label goes).
--
-- WHAT DOES NOT MOVE. The title, status and the row itself; on a pick B tier
-- also every field (key, label, unit, expected, tol and position) and the
-- dataset.
--
-- ATTEMPTS. Tiers this file re-keys: welldata/intermediate, welldata/advanced.
-- Before it writes, the file counts academy_capstone_attempts on each and
-- REFUSES if any exist, unless D5 allowlists that tier with the exact attempt
-- ids (allowlist: empty). Stored scores are never touched.
--
-- GUARDS. Each row must hold EITHER its post-W1 prompt and dataset (by md5)
-- and fields (exact jsonb), as production holds them after the W1 34 files
-- (it is rewritten), OR its W5 form (left alone). Anything else raises and the
-- whole file rolls back. Lessons and panels ship with the NextGen zip, near-
-- simultaneous with this apply. Generated by
-- docs/graded-field-audit/w5c_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
begin
  -- welldata / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'welldata' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w5c welldata refused: welldata/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'f1f9dc40f987775a462d8673843a6460' and md5(dataset) = '862143a20448026fdd6c8cdde9059662' and fields = '[{"key": "start_md_m", "tol": 0.01, "unit": "m", "label": "feet_20: start depth (converted)", "expected": 1493.52001953125}, {"key": "stop_md_m", "tol": 0.01, "unit": "m", "label": "feet_20: stop depth (converted)", "expected": 1584.9599609375}, {"key": "step_m", "tol": 0.001, "unit": "m", "label": "feet_20: depth step (converted)", "expected": 0.609619140625}, {"key": "converted_curves", "tol": 0, "unit": "count", "label": "feet_20: curves unit-converted", "expected": 2}, {"key": "recognized_kinds", "tol": 0, "unit": "count", "label": "feet_20: curve kinds recognised", "expected": 4}, {"key": "irregular_samples", "tol": 0, "unit": "count", "label": "irregular_20: depth samples", "expected": 121}]'::jsonb then 'old'
              when md5(prompt) = '0156b5f2eb1c492285f021f5b1ce6662' and md5(dataset) = '96a0b5d966a539b47757db2488bcb789' and fields = '[{"key": "oduma3_start_md_m", "tol": 0.01, "unit": "m", "label": "oduma3_feet: start depth (converted)", "expected": 2139.696044921875}, {"key": "oduma3_stop_md_m", "tol": 0.01, "unit": "m", "label": "oduma3_feet: stop depth (converted)", "expected": 2169.26171875}, {"key": "oduma3_import_step_m", "tol": 0.001, "unit": "m", "label": "oduma3_feet: depth step (converted)", "expected": 0.076171875}, {"key": "oduma3_converted_curves", "tol": 0, "unit": "count", "label": "oduma3_feet: curves unit-converted", "expected": 3}, {"key": "oduma3_recognized_kinds", "tol": 0, "unit": "count", "label": "oduma3_feet: curve kinds recognised", "expected": 6}, {"key": "oduma4_n_samples", "tol": 0, "unit": "count", "label": "oduma4_irregular: depth samples", "expected": 173}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'welldata' and tier = 'intermediate' and active;
  if v_s0 = 'other' then
    raise exception 'w5c welldata refused: welldata/intermediate matches neither its post-W1 form (prompt md5 f1f9dc40f987775a462d8673843a6460) nor its W5 form (prompt md5 0156b5f2eb1c492285f021f5b1ce6662), with the dataset and fields this file was generated against';
  end if;

  -- welldata / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'welldata' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w5c welldata refused: welldata/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'afcf8eee7d3e7053b92c405d350fd513' and md5(dataset) = '7059fca16c00cc99b6c32784eec52848' and fields = '[{"key": "campaign_curves", "tol": 0, "unit": "count", "label": "Curves imported across the campaign", "expected": 24}, {"key": "converted_files", "tol": 0, "unit": "count", "label": "Files needing depth unit conversion", "expected": 1}, {"key": "dead_curves", "tol": 0, "unit": "count", "label": "Dead curves detected", "expected": 1}, {"key": "uniform_files", "tol": 0, "unit": "count", "label": "Files with a uniform depth step", "expected": 5}, {"key": "wrapped_samples", "tol": 0, "unit": "count", "label": "Depth samples in wrapped_12", "expected": 161}, {"key": "nullheavy_nulls", "tol": 0, "unit": "count", "label": "Flagged nulls in nullheavy_20", "expected": 272}]'::jsonb then 'old'
              when md5(prompt) = '889739254184970e786775ed17c5a087' and md5(dataset) = 'efcf02165b4602ef5e8299586605f920' and fields = '[{"key": "oduma_campaign_curves", "tol": 0, "unit": "count", "label": "Curves imported across the ODUMA campaign", "expected": 31}, {"key": "oduma_converted_files", "tol": 0, "unit": "count", "label": "Files needing depth unit conversion", "expected": 3}, {"key": "oduma_dead_curves", "tol": 0, "unit": "count", "label": "Dead curves detected", "expected": 2}, {"key": "oduma_uniform_files", "tol": 0, "unit": "count", "label": "Files with a uniform depth step", "expected": 4}, {"key": "oduma1_wrapped_samples", "tol": 0, "unit": "count", "label": "Depth samples in oduma1_wrapped", "expected": 207}, {"key": "oduma5_flagged_nulls", "tol": 0, "unit": "count", "label": "Flagged nulls in oduma5_nulls", "expected": 525}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'welldata' and tier = 'advanced' and active;
  if v_s1 = 'other' then
    raise exception 'w5c welldata refused: welldata/advanced matches neither its post-W1 form (prompt md5 afcf8eee7d3e7053b92c405d350fd513) nor its W5 form (prompt md5 889739254184970e786775ed17c5a087), with the dataset and fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W5 form
  if v_s0 = 'new' and v_s1 = 'new' then
    raise notice 'w5c welldata: 0 of 2 row(s) written, all already applied';
    return;
  end if;

  -- ATTEMPTS. A tier whose graded keys this file moves must hold no capstone
  -- attempt (a stored score is never re-scored, but a learner could be graded
  -- differently on a retry), unless D5 allowlists it with the exact attempt
  -- ids signed off. Any other attempt refuses.
  if v_s0 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'welldata' and a.tier = 'intermediate';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'welldata/intermediate' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'welldata/intermediate') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_extra) x;
          raise exception 'w5c welldata refused: welldata/intermediate holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_idtxt;
        end if;
        raise notice 'w5c welldata: welldata/intermediate holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_ids) x;
        raise exception 'w5c welldata refused: welldata/intermediate holds % capstone attempt(s) (%) and this file re-keys it; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_idtxt;
      end if;
    end if;
  end if;
  if v_s1 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'welldata' and a.tier = 'advanced';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'welldata/advanced' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'welldata/advanced') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_extra) x;
          raise exception 'w5c welldata refused: welldata/advanced holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_idtxt;
        end if;
        raise notice 'w5c welldata: welldata/advanced holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_ids) x;
        raise exception 'w5c welldata refused: welldata/advanced holds % capstone attempt(s) (%) and this file re-keys it; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_idtxt;
      end if;
    end if;
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Run the full import pipeline on oduma3_feet.las from the ODUMA capstone case files (download them from this card and open them in the import explorer with Open your own LAS files) and read the import panel: the start depth, the stop depth and the depth step converted to metres, how many curves needed unit conversion, and how many curve kinds the importer recognised. Then report the number of depth samples in oduma4_irregular.las, the case file whose depth step changes size down the log.',
           dataset = 'ODUMA capstone case: oduma3_feet and oduma4_irregular, downloaded from the capstone card',
           fields = '[{"key": "oduma3_start_md_m", "tol": 0.01, "unit": "m", "label": "oduma3_feet: start depth (converted)", "expected": 2139.696044921875}, {"key": "oduma3_stop_md_m", "tol": 0.01, "unit": "m", "label": "oduma3_feet: stop depth (converted)", "expected": 2169.26171875}, {"key": "oduma3_import_step_m", "tol": 0.001, "unit": "m", "label": "oduma3_feet: depth step (converted)", "expected": 0.076171875}, {"key": "oduma3_converted_curves", "tol": 0, "unit": "count", "label": "oduma3_feet: curves unit-converted", "expected": 3}, {"key": "oduma3_recognized_kinds", "tol": 0, "unit": "count", "label": "oduma3_feet: curve kinds recognised", "expected": 6}, {"key": "oduma4_n_samples", "tol": 0, "unit": "count", "label": "oduma4_irregular: depth samples", "expected": 173}]'::jsonb
     where app_slug = 'welldata' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w5c welldata refused: welldata/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '0156b5f2eb1c492285f021f5b1ce6662' and md5(dataset) = '96a0b5d966a539b47757db2488bcb789' and fields = '[{"key": "oduma3_start_md_m", "tol": 0.01, "unit": "m", "label": "oduma3_feet: start depth (converted)", "expected": 2139.696044921875}, {"key": "oduma3_stop_md_m", "tol": 0.01, "unit": "m", "label": "oduma3_feet: stop depth (converted)", "expected": 2169.26171875}, {"key": "oduma3_import_step_m", "tol": 0.001, "unit": "m", "label": "oduma3_feet: depth step (converted)", "expected": 0.076171875}, {"key": "oduma3_converted_curves", "tol": 0, "unit": "count", "label": "oduma3_feet: curves unit-converted", "expected": 3}, {"key": "oduma3_recognized_kinds", "tol": 0, "unit": "count", "label": "oduma3_feet: curve kinds recognised", "expected": 6}, {"key": "oduma4_n_samples", "tol": 0, "unit": "count", "label": "oduma4_irregular: depth samples", "expected": 173}]'::jsonb) from public.academy_capstones where app_slug = 'welldata' and tier = 'intermediate' and active) is not true then
    raise exception 'w5c welldata refused: welldata/intermediate does not read back as its W5 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Run the full import pipeline on all six ODUMA capstone case files as one campaign (download them from this card and open them together in the campaign explorer with Open your own LAS files as a campaign) and read the campaign panel: total curves imported (depth excluded), files needing depth unit conversion, dead curves detected, files with a uniform depth step, depth samples parsed from the wrapped LAS 1.2 file oduma1_wrapped, and total flagged nulls in oduma5_nulls.',
           dataset = 'ODUMA capstone case: all six LAS files, downloaded from the capstone card',
           fields = '[{"key": "oduma_campaign_curves", "tol": 0, "unit": "count", "label": "Curves imported across the ODUMA campaign", "expected": 31}, {"key": "oduma_converted_files", "tol": 0, "unit": "count", "label": "Files needing depth unit conversion", "expected": 3}, {"key": "oduma_dead_curves", "tol": 0, "unit": "count", "label": "Dead curves detected", "expected": 2}, {"key": "oduma_uniform_files", "tol": 0, "unit": "count", "label": "Files with a uniform depth step", "expected": 4}, {"key": "oduma1_wrapped_samples", "tol": 0, "unit": "count", "label": "Depth samples in oduma1_wrapped", "expected": 207}, {"key": "oduma5_flagged_nulls", "tol": 0, "unit": "count", "label": "Flagged nulls in oduma5_nulls", "expected": 525}]'::jsonb
     where app_slug = 'welldata' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w5c welldata refused: welldata/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '889739254184970e786775ed17c5a087' and md5(dataset) = 'efcf02165b4602ef5e8299586605f920' and fields = '[{"key": "oduma_campaign_curves", "tol": 0, "unit": "count", "label": "Curves imported across the ODUMA campaign", "expected": 31}, {"key": "oduma_converted_files", "tol": 0, "unit": "count", "label": "Files needing depth unit conversion", "expected": 3}, {"key": "oduma_dead_curves", "tol": 0, "unit": "count", "label": "Dead curves detected", "expected": 2}, {"key": "oduma_uniform_files", "tol": 0, "unit": "count", "label": "Files with a uniform depth step", "expected": 4}, {"key": "oduma1_wrapped_samples", "tol": 0, "unit": "count", "label": "Depth samples in oduma1_wrapped", "expected": 207}, {"key": "oduma5_flagged_nulls", "tol": 0, "unit": "count", "label": "Flagged nulls in oduma5_nulls", "expected": 525}]'::jsonb) from public.academy_capstones where app_slug = 'welldata' and tier = 'advanced' and active) is not true then
    raise exception 'w5c welldata refused: welldata/advanced does not read back as its W5 form';
  end if;

  raise notice 'w5c welldata: % of 2 row(s) written, % already applied', v_written, 2 - v_written;
end $$;
